 const Primary=({children}:{children:React.ReactNode})=><Button type="submit" className="wide" disabled={loading||offline||(['activar','aviso'].includes(m.view)&&!accepted)}>{loading?t('Guardando…','Saving…'):children}{!loading&&<ArrowRight/>}</Button>;
 const Notice=()=> <><details className="notice" open><summary>{t('Aviso de tratamiento de datos','Personal data notice')} · v1</summary><p>{t(noticeEs,noticeEn)}</p><p className="legal">{t('Texto pendiente de revisión legal. Los campos entre corchetes deben completarse antes de invitar usuarios reales.','Pending legal review. Bracketed fields must be completed before inviting real users.')}</p></details><label className="checkline" htmlFor="accept"><Checkbox id="accept" checked={accepted} onCheckedChange={v=>setAccepted(v===true)} disabled={loading}/><span>{t('He leído el aviso v1 y autorizo el tratamiento descrito.','I have read notice v1 and authorize the processing described.')}</span></label></>;
 const genericError=()=>m.view==='login'?t('No pudimos iniciar sesión. Revisa el correo y la contraseña. Después de varios intentos fallidos debes esperar quince minutos.','We could not sign you in. Check your email and password. After several failed attempts you must wait fifteen minutes.'):m.view==='invitar'?t('Este correo ya está registrado. Busca la cuenta para cambiar su acceso o generar un enlace nuevo.','This email is already registered. Find the account to change access or generate a new link.'):t('No pudimos guardar los cambios. Tus datos siguen aquí; vuelve a intentarlo.','We could not save your changes. Your entries are still here; try again.');
 const StateNotice=()=> <>{error&&<div role="alert" className="note bad">{genericError()}</div>}{offline&&<div role="alert" className="note bad">{t('Sin conexión. Conservamos los datos en esta vista; vuelve a intentarlo cuando te conectes.','Offline. Your entries remain in this view; reconnect and try again.')} <Button variant="link" style={{color:'var(--destructive)'}} onClick={()=>m.set('state','normal')}>{t('Reintentar','Retry')}</Button></div>}{invalid&&<div role="alert" className="note bad">{m.view==='rol'?t('El rol necesita un nombre y al menos un permiso.','The role needs a name and at least one permission.'):t('Revisa los campos. La contraseña debe tener al menos 8 caracteres y ambas deben coincidir.','Check the fields. Passwords must have at least 8 characters and match.')}</div>}</>;
 const skeleton=()=> <div className="stack" role="status" aria-label={t('Cargando contenido','Loading content')}>{[0,1,2,3].map(i=><Skeleton key={i} style={{height:i?44:22,width:i===0?'65%':'100%',background:'var(--muted)'}}/>)}<p className="help">{t('Cargando…','Loading…')}</p></div>;
 const successText=()=>m.view==='cuenta'?t('Contraseña actualizada. Se cerraron las otras sesiones; este navegador tiene una sesión nueva.','Password updated. Other sessions ended; this browser has a new session.'):m.view==='restablecer'?t('Contraseña guardada. Ya puedes iniciar sesión con la nueva contraseña.','Password saved. You can now sign in with the new password.'):m.view==='aviso'?t('Aceptación guardada: aviso v1 · 26 oct 2026. Ya puedes continuar.','Acceptance saved: notice v1 · 26 Oct 2026. You can continue.'):t('Sesión iniciada. Tu cuenta tiene acceso a las herramientas del Plan 2.','Signed in. Your account has access to the Plan 2 tools.');
 const title=({login:t('Iniciar sesión','Sign in'),activar:t('Activa tu cuenta','Activate your account'),restablecer:t('Restablecer contraseña','Reset password'),aviso:t('Revisa el nuevo aviso','Review the new notice'),cuenta:t('Mi cuenta','My account'),invitar:t('Invitar persona','Invite person'),cuentas:t('Cuentas','Accounts'),roles:t('Roles y permisos','Roles and permissions'),rol:t('Crear o editar rol','Create or edit role')} as Record<string,string>)[m.view];
